  1394  void CairoOutputDev::drawChar(GfxState *state, double x, double y,
  1395                                double dx, double dy,
  1396                                double originX, double originY,
  1397                                CharCode code, int nBytes, Unicode *u, int uLen)
  1398  {
  1399    if (currentFont) {
  1400      glyphs[glyphCount].index = currentFont->getGlyph (code, u, uLen);
  1401      glyphs[glyphCount].x = x - originX;
  1402      glyphs[glyphCount].y = y - originY;
  1403      glyphCount++;
  1404      if (use_show_text_glyphs) {
  1405        GooString enc("UTF-8");
  1406        UnicodeMap *utf8Map = globalParams->getUnicodeMap(&enc);
  1407        if (utf8Max - utf8Count < uLen*6) {
  1408          // utf8 encoded characters can be up to 6 bytes
  1409          if (utf8Max > uLen*6)
  1410            utf8Max *= 2;
  1411          else
  1412            utf8Max += 2*uLen*6;
  1413          utf8 = (char *) grealloc (utf8, utf8Max);
  1414        }
  1415        clusters[clusterCount].num_bytes = 0;
  1416        for (int i = 0; i < uLen; i++) {
  1417          int size = utf8Map->mapUnicode(u[i], utf8 + utf8Count, utf8Max - utf8Count);
  1418          utf8Count += size;
  1419          clusters[clusterCount].num_bytes += size;
  1420        }
  1421        clusters[clusterCount].num_glyphs = 1;
  1422        clusterCount++;
  1423      }
  1424    }
  1425
  1426    if (!text)
  1427      return;
  1428    actualText->addChar (state, x, y, dx, dy, code, nBytes, u, uLen);
  1429  }
