  1431  void CairoOutputDev::endString(GfxState *state)
  1432  {
  1433    int render;
  1434
  1435    if (!currentFont)
  1436      return;
  1437
  1438    // endString can be called without a corresponding beginString. If this
  1439    // happens glyphs will be null so don't draw anything, just return.
  1440    // XXX: OutputDevs should probably not have to deal with this...
  1441    if (!glyphs)
  1442      return;
  1443
  1444    // ignore empty strings and invisible text -- this is used by
  1445    // Acrobat Capture
  1446    render = state->getRender();
  1447    if (render == 3 || glyphCount == 0 || !text_matrix_valid) {
  1448      goto finish;
  1449    }
  1450
  1451    if (!(render & 1)) {
  1452      LOG (printf ("fill string\n"));
  1453      cairo_set_source (cairo, fill_pattern);
  1454      if (use_show_text_glyphs)
  1455        cairo_show_text_glyphs (cairo, utf8, utf8Count, glyphs, glyphCount, clusters, clusterCount, (cairo_text_cluster_flags_t)0);
  1456      else
  1457          cairo_show_glyphs (cairo, glyphs, glyphCount);
  1458      if (cairo_shape)
  1459        cairo_show_glyphs (cairo_shape, glyphs, glyphCount);
  1460    }
  1461
  1462    // stroke
  1463    if ((render & 3) == 1 || (render & 3) == 2) {
  1464      LOG (printf ("stroke string\n"));
  1465      cairo_set_source (cairo, stroke_pattern);
  1466      cairo_glyph_path (cairo, glyphs, glyphCount);
  1467      cairo_stroke (cairo);
  1468      if (cairo_shape) {
  1469        cairo_glyph_path (cairo_shape, glyphs, glyphCount);
  1470        cairo_stroke (cairo_shape);
  1471      }
  1472    }
  1473
  1474    // clip
  1475    if ((render & 4)) {
  1476      LOG (printf ("clip string\n"));
  1477      // append the glyph path to textClipPath.
  1478
  1479      // set textClipPath as the currentPath
  1480      if (textClipPath) {
  1481        cairo_append_path (cairo, textClipPath);
  1482        if (cairo_shape) {
  1483          cairo_append_path (cairo_shape, textClipPath);
  1484        }
  1485        cairo_path_destroy (textClipPath);
  1486      }
  1487
  1488      // append the glyph path
  1489      cairo_glyph_path (cairo, glyphs, glyphCount);
  1490
  1491      // move the path back into textClipPath
  1492      // and clear the current path
  1493      textClipPath = cairo_copy_path (cairo);
  1494      cairo_new_path (cairo);
  1495      if (cairo_shape) {
  1496        cairo_new_path (cairo_shape);
  1497      }
  1498    }
  1499
  1500  finish:
  1501    gfree (glyphs);
  1502    glyphs = nullptr;
  1503    if (use_show_text_glyphs) {
  1504      gfree (clusters);
  1505      clusters = nullptr;
  1506      gfree (utf8);
  1507      utf8 = nullptr;
  1508    }
  1509  }
